'use strict';
const video=document.querySelector('#video'),status=document.querySelector('#status'),list=document.querySelector('#matches'),retry=document.querySelector('#retry');
let matches=[],current=null,pendingSeek=null,pendingPlay=false,lastSaved=0;
const fmt=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
function message(text){status.textContent=text;status.hidden=!text;}
function remember(){if(!current||!Number.isFinite(video.currentTime))return;try{localStorage.setItem('six-battles:'+current.id,String(video.currentTime));}catch{}}
function seekPlay(seconds){if(video.readyState>=1){video.currentTime=Math.min(seconds,Math.max(0,video.duration-1));video.play().catch(()=>message('点击视频中的播放按钮开始观看'));}else{pendingSeek=seconds;pendingPlay=true;video.load();}}
function select(match){remember();current=match;pendingSeek=null;pendingPlay=false;video.pause();video.removeAttribute('src');video.load();message('正在加载视频…');retry.hidden=true;document.querySelector('#title').textContent='Agnes vs '+match.displayName;const result=document.querySelector('#result');result.textContent=match.our_result==='win'?'我方获胜':'我方落败';result.className='result '+match.our_result;document.querySelector('#map').textContent=match.mapLabel;document.querySelector('#duration').textContent=fmt(match.videoDuration)+' 视频';document.querySelector('#download').href=match.replay;video.poster=match.poster;video.src=match.video;video.playbackRate=Number(document.querySelector('#speed').value);try{const saved=Number(localStorage.getItem('six-battles:'+match.id));if(saved>0&&saved<match.videoDuration-3)pendingSeek=saved;}catch{}document.querySelectorAll('.match').forEach(el=>{const active=el.dataset.id===match.id;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});const url=new URL(location.href);url.searchParams.set('match',match.id);history.replaceState(null,'',url);video.load();}
video.addEventListener('loadedmetadata',()=>{video.playbackRate=Number(document.querySelector('#speed').value);if(pendingSeek!==null){video.currentTime=Math.min(pendingSeek,Math.max(0,video.duration-1));pendingSeek=null;}message('点击播放，或直接跳到交战');if(pendingPlay){pendingPlay=false;video.play().catch(()=>message('点击视频中的播放按钮开始观看'));}});
video.addEventListener('playing',()=>message(''));video.addEventListener('waiting',()=>message('正在缓冲…'));video.addEventListener('seeked',()=>{if(!video.paused)message('');else message('已定位，点击播放继续');});video.addEventListener('error',()=>{message('视频加载失败，请重新加载；也可以下载原始回放。');retry.hidden=false;});video.addEventListener('ended',()=>{message('本局播放结束，可从列表选择下一局');remember();});video.addEventListener('timeupdate',()=>{if(Date.now()-lastSaved>3000){remember();lastSaved=Date.now();}});window.addEventListener('pagehide',remember);
document.querySelector('#from-start').onclick=()=>seekPlay(0);document.querySelector('#combat').onclick=()=>{if(current)seekPlay(current.combatSeconds);};document.querySelector('#speed').onchange=e=>{video.defaultPlaybackRate=video.playbackRate=Number(e.target.value);};retry.onclick=()=>{const time=video.currentTime||0;pendingSeek=time;message('正在重新加载…');retry.hidden=true;video.load();};
fetch('matches.json').then(r=>{if(!r.ok)throw new Error('比赛列表加载失败');return r.json();}).then(data=>{matches=data;for(const [index,match] of matches.entries()){const button=document.createElement('button');button.className='match';button.dataset.id=match.id;button.setAttribute('aria-pressed','false');button.innerHTML=`<span class="number">${String(index+1).padStart(2,'0')}</span><span><span class="opponent"><span></span><span class="mini-result ${match.our_result}">${match.our_result==='win'?'胜':'负'}</span></span><span class="source-label"></span><span class="card-meta"><span></span><span>${fmt(match.videoDuration)}</span></span></span>`;button.querySelector('.opponent>span').textContent=match.displayName;button.querySelector('.source-label').textContent=match.opponent.includes('Candidate')?'作者源码候选 · 身份未确认':'';button.querySelector('.card-meta>span').textContent=match.mapLabel;button.onclick=()=>select(match);list.append(button);}const id=new URLSearchParams(location.search).get('match');select(matches.find(m=>m.id===id)||matches[0]);}).catch(e=>message(e.message));
